import assert from 'node:assert/strict';
import { mean, median } from '../src/stats.js';
test('mean', () => assert.equal(mean([1, 2, 3, 6]), 3));
test('median odd', () => assert.equal(median([5, 1, 3]), 3));
test('median even', () => assert.equal(median([4, 1, 3, 2]), 2.5));
test('empty throws', () => { assert.throws(() => mean([]), RangeError); assert.throws(() => median([]), RangeError); });

